content.text:
            cnt[i] ^= mask
            mask = carry
            i += 1

    def counts(self, n):
        res = [0] * n
        for j, b in enumerate(self.cnt):
            if not b:
                continue
            bit = 1 << j
            while b:
                low = b & -b
                res[low.bit_length() - 1] |= bit
                b ^= low
        return res


# ----------------------------------------------------------------------------
# Mining
# ----------------------------------------------------------------------------

def compute(K, B, S, W, natoms, atom_fns, tsources, train_ctx, probe_ctx,
            query_ctx):
    ntrain = len(train_ctx)
    nprobe = len(probe_ctx)
    nquery = len(query_ctx)
    ns = len(tsources)

    # atom truth values ---------------------------------------------------
    ttrain = [[f(c[2]) for c in train_ctx] for f in atom_fns]
    tprobe = [[f(c[2]) for c in probe_ctx] for f in atom_fns]
    tquery = [[f(c[2]) for c in query_ctx] for f in atom_fns]

    ALLTRAIN = (1 << ntrain) - 1
    ALLPROBE = (1 << nprobe) - 1 if nprobe else -1
    QMASK = (1 << nquery) - 1

    # per literal truth bitmasks ------------------------------------------
    nlit = 2 * natoms
    lmask = [0] * nlit          # over training contexts
    lprobe = [0] * nlit         # over probe contexts
    lquery = [0] * nlit         # over query contexts
    for ai in range(natoms):
        tv = ttrain[ai]
        m = 0
        for ci, v in enumerate(tv):
            if v:
                m |= 1 << ci
        lmask[2 * ai] = m
        lmask[2 * ai + 1] = ALLTRAIN ^ m
        pv = tprobe[ai]
        m = 0
        for ci, v in enumerate(pv):
            if v:
                m |= 1 << ci
        lprobe[2 * ai] = m
        lprobe[2 * ai + 1] = ALLPROBE ^ m
        qv = tquery[ai]
        m = 0
        for ci, v in enumerate(qv):
            if v:
                m |= 1 << ci
        lquery[2 * ai] = m
        lquery[2 * ai + 1] = QMASK ^ m

    # sources --------------------------------------------------------------
    src_index = {}
    for i, s in enumerate(tsources):
        src_index[s] = i
    srcmask = [0] * ns
    for ci, c in enumerate(train_ctx):
        si = src_index[c[3]]
        srcmask[si] |= 1 << ci
    # per literal, per source masks
    lsrc = []
    for li in range(nlit):
        row = []
        for si in range(ns):
            row.append(lmask[li] & srcmask[si])
        lsrc.append(row)

    classes = {}
    if natoms > 0 and ns > 0 and nprobe > 0:
        # condition 2: per source support
        elig = []
        for li in range(nlit):
            ok = True
            row = lsrc[li]
            for si in range(ns):
                if row[si].bit_count() < S:
                    ok = False
                    break
            if ok:
                elig.append(li)
        elig_set = set(elig)
        if elig:
            elig_by_atom = []
            for ai in range(natoms):
                cur = []
                for li in (2 * ai, 2 * ai + 1):
                    if li in elig_set:
                        cur.append(li)
                elig_by_atom.append(cur)
            elig_atoms = [ai for ai in range(natoms) if elig_by_atom[ai]]

            def witnesses_ok(lits):
                k = len(lits)
                if k == 1:
                    row = lsrc[lits[0]]
                    for si in range(ns):
                        if row[si].bit_count() < W:
                            return False
                    return True
                for si in range(ns):
                    sm = srcmask[si]
                    ms = [lsrc[l][si] for l in lits]
                    suf = [0] * (k + 1)
                    for i in range(k - 1, -1, -1):
                        suf[i] = ms[i] | suf[i + 1]
                    pre = 0
                    for i in range(k):
                        others = pre | suf[i + 1]
                        if (ms[i] & (sm ^ others)).bit_count() < W:
                            return False
                        pre = pre | ms[i]
                return True

            def record(lits, psig):
                ct = 0
                for li in lits:
                    ct |= lquery[li]
                e = classes.get(psig)
                if e is None:
                    classes[psig] = [1, lits, ct, ct]
                else:
                    e[0] += 1
                    e[2] |= ct
                    e[3] &= ct

            def dfs(start, lits, cov, psig):
                if psig == ALLPROBE:
                    return
                if not witnesses_ok(lits):
                    return
                if cov == ALLTRAIN:
                    record(lits, psig)
                if len(lits) == B:
                    return
                for pos in range(start, len(elig_atoms)):
                    ai = elig_atoms[pos]
                    for li in elig_by_atom[ai]:
                        dfs(pos + 1, lits + (li,), cov | lmask[li],
                            psig | lprobe[li])

            dfs(0, (), 0, 0)

    # query answers ---------------------------------------------------------
    hexlen = (nprobe + 3) // 4
    out_classes = []
    mctr = BitCounters()
    yctr = BitCounters()
    for psig, entry in classes.items():
        cnt, repr_lits, oracc, andacc = entry
        out_classes.append({
            'signature': format(psig, 'x').zfill(hexlen),
            'members': cnt,
            'representative': {
                'or': [{'atom': li // 2, 'negated': (li % 2) == 1}
                       for li in repr_lits]
            },
        })
        if nquery:
            mctr.add(QMASK & ~oracc)
            yctr.add(QMASK & ~andacc)

    if nquery:
        mcounts = mctr.counts(nquery)
        ycounts = yctr.counts(nquery)
    else:
        mcounts = []
        ycounts = []

    out_queries = []
    for q in range(nquery):
        m = mcounts[q]
        y = ycounts[q]
        if m > 0:
            st = 'violating'
        elif y > 0:
            st = 'ambiguous'
        else:
            st = 'consistent'
        out_queries.append({'trace': query_ctx[q][0], 'end': query_ctx[q][1],
                            'must': m, 'may': y, 'status': st})

    return {'version': 1, 'classes': out_classes, 'queries': out_queries}


