def emit(obj):
    sys.stdout.write(json.dumps(obj, separators=(',', ':')))
    sys.stdout.write('\n')


def main():
    data = sys.stdin.buffer.read()
    if len(data) > MAXBYTES:
        emit({'error': 'E_LIMIT'})
